"""Append W6 conditional design point while preserving W5 as-built evidence."""
import json,re,hashlib,datetime,math
from pathlib import Path
from area_models import configure,block_area
W=Path(__file__).resolve().parent;R=W.parent.parent
cfg=json.loads((W/'blocks_credible.json').read_text());runs=json.loads((W/'credible_runs.json').read_text());rows=json.loads((W/'credible_area_table.json').read_text())
def summarize(run):
 p=W/'runs'/run['name'];m=json.loads((p/'manifest.json').read_text());log=(W/'logs'/(run['name']+'.log')).read_text();drops=[float(v) for v in re.findall(r'Worstcase IR drop:\s*([\d.eE+-]+)',log)];assert len(drops)==2,run['name']
 short=json.loads((p/'floorplan.odb.shorts.json').read_text());boxes=[(t['x']-30,t['y']-30,t['x']+t['w']+30,t['y']+t['h']+30) for t in m['tiles']]
 overlaps=sum(min(a[2],b[2])>max(a[0],b[0]) and min(a[3],b[3])>max(a[1],b[1]) for i,a in enumerate(boxes) for b in boxes[i+1:]);legal=not overlaps and all(a[0]>=700 and a[1]>=700 and a[2]<=m['die_width_mm']*1000-700 and a[3]<=m['die_height_mm']*1000-700 for a in boxes)
 r={k:v for k,v in m.items() if k not in ['tiles','pads']};r.update(name=run['name'],placement_legal_check=legal,macro_overlap_count=overlaps,pdn_pass=all(f'W3_CONNECTIVITY_{net}_PASS' in log for net in ['VDD','VSS']),ir_solver_pass=all(f'W3_IR_{net}_PASS' in log for net in ['VDD','VSS']),worst_ir_drop_v=drops[0],worst_ground_rise_v=drops[1],combined_worst_bound_v=sum(drops),ir_5pct_pass=sum(drops)<.165,short_check=short,execution=json.loads((p/'execution.json').read_text()),fits_assumed26x33_reticle=min(m['die_width_mm'],m['die_height_mm'])<=26 and max(m['die_width_mm'],m['die_height_mm'])<=33,requires_custom_sram=m['memory']=='sram_dense_custom',requires_accuracy_revalidation=m['levers']=='on',artifacts={k:str((p/v).relative_to(W)) for k,v in [('png','floorplan.png'),('heatmap','ir_heatmap.png'),('def','floorplan.def'),('odb','floorplan.odb'),('tcl','floorplan.tcl'),('lef','macros.lef'),('voltage_vdd','VDD_voltage.rpt'),('voltage_vss','VSS_voltage.rpt')]})
 r['physical_screen_pass']=legal and r['pdn_pass'] and r['ir_solver_pass'] and r['ir_5pct_pass'] and short['short_count']==0
 return r
physical=[summarize(r) for r in runs];assert all(p['physical_screen_pass'] for p in physical)
sourcecheck=[]
for s,h in cfg['pitch_source_hashes'].items():
 actual=hashlib.sha256((R/s).read_bytes()).hexdigest();sourcecheck.append(dict(source=s,snapshot_sha256=h['sha256'],current_sha256=actual,unchanged=actual==h['sha256']))
blocktable=[]
for lever in ['off','on','books']:
 c=configure(cfg,'sram_open_macro',lever);blocktable.append(dict(levers=lever,blocks=[dict(name=b['name'],**block_area(c,b,'pitch1280v2'),source=b['source'],area_status=b['area_status'],power_assumed_w=b['power_w']) for b in c['blocks']]))
density=cfg['scenarios']['pitch1280v2']['selection_um2'];v=cfg['pitch_verification'];drc1280=v['1280'].get('selected_drc');lvs1280=v['1280'].get('lvs');drc64=v['64'].get('selected_drc');lvs64=v['64'].get('lvs')
result=dict(updated_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),scope='Conditional credible design point, not tapeout or full recognizer proof',measured_selection_density_um2=density,density_label='MEASURED GDS bounding rectangle incl analog readout; DRC/LVS scope below',source_hashes=cfg['pitch_source_hashes'],final_source_check=sourcecheck,array_verification=v,array_timing=cfg['pitch_timing'],array_missing=cfg['pitch_missing'],uniform_whole_model_array_mm2=density*31457280/1e6,nonreceiver_access_allowance_mm2=56.584,additional_books_in_array_access_allowance_mm2=28.292,allowance_status='ASSUMED transfer of October nonreceiver component subtotal, not a measured W5 integrated macro',area_table=rows,block_area_tables=blocktable,physical_cases=physical,outline_search='credible_outline_search.json',minimum_scope='Smallest integer-mm rectangle within recorded shelf-packing search; not global geometric minimum',reticle_assumption_mm=[26,33],engine_model=cfg['engine_model'],levers=cfg['levers_definition'],frozen_memory_source='as_built_tonight_blocks.json and memory_allocation.json',mutable_array_bits=8501818,ordinary_register_bits=237524,accuracy_preserving_candidate='Two open-SRAM books-only dies; frontendFP32, originalKV, no book dedup',complete_array_macro_proven=False,working_functional_pad_interface_proven=False,subwatt_proven=False,power_measured=False,commands='CREDIBLE_COMMANDS.md',preserved_superseded_attempts='credible_superseded_access_allowance.json',input_refresh_audit='credible_input_refresh_audit.json')
(W/'credible_results.json').write_text(json.dumps(result,indent=2)+'\n');base=json.loads((W/'as_built_tonight_results.json').read_text());base['credible_taalas_design_point']=result;base['updated_utc']=result['updated_utc'];base['status']='as_built_and_credible_abstract_screens_complete; implementation_qualification_pending';(W/'results.json').write_text(json.dumps(base,indent=2)+'\n')
def drc_text(v):
 return 'pending' if v is None else str(v.get('drc_markers','unknown'))+' markers; selected FEOL/BEOL/connectivity/off-grid checks, density and antenna excluded'
def lvs_text(v):
 if v is None:return 'pending'
 if v.get('pass') is True:return 'PASS: unique match, no property errors'
 return str(v.get('status','unqualified'))+'; see machine record'
labels=['One die: dense SRAM, frontend INT8 + books array','Two-die INT8 / open SRAM: A','Two-die INT8 / open SRAM: B','Two-die FP32 / open SRAM: A','Two-die FP32 / open SRAM: B']
lines=['## Credible Taalas design point','',f"Frozen W6 snapshot **{cfg['pitch_snapshot_utc']}**; report {result['updated_utc']}.",'', '**The pitch-matched array gives a conditional route to one reticle-sized die with custom dense SRAM and frontend INT8, or two reticle-sized dies using the open SRAMs and unchanged numerical formats.** The smallest screened one-die case is **25 × 31 mm**. The strongest available option avoiding both custom SRAM and numerical changes is **two 26 × 29 mm dies**, with FP32 frontend, original mutable state and books stored in the readable array. All five selected outlines pass abstract placement, VDD/VSS connectivity and the combined 5% IR criterion under assumed loads. The 26 × 33 mm field remains a planning assumption. Full W6 macro qualification/timing, memory port mapping, row-bus and cross-die access, functional pad signals, signal routing and measured workload power remain open. These results are a physical component screen, not a finished recognizer or tapeout claim.','', '### New array evidence and remaining assumptions','', f"Selection density is **MEASURED {density:.9f} µm²/selection including analog readout**: W6’s 1,280 × 320 bank is 1004 × 2258.81 µm = 2.26784524 mm². All 1,638,400 programmed bits read back from GDS with zero mismatches. Full-bank selected DRC status: **{drc_text(drc1280)}**. Full-bank LVS status: **{lvs_text(lvs1280)}**. The separate 64-row selected DRC reports **{drc64.get('drc_markers') if drc64 else 'pending'} markers**; its LVS status is **{lvs_text(lvs64)}**. The complete raw verification records and hashes are in `credible_results.json`; a small-slice pass is not transferred to the full bank.", '', 'The 31,457,280 fixed selections occupy 174.170514 mm² at this uniform density. W6 replaces the wide horizontal receiver strip with eight stacked receiver rows, retaining the narrow native array pitch; this removes the major blank-width penalty identified in the earlier W5 report. This remains a uniform-density extrapolation, not a physical allocation of all 98 matrix shapes, their padding, ports or tied-table transpose access. Whole-chip macros are area-derived rectangular abstracts; the flow does not place the exact 1004 ×2258.81 µm W6 bank GDS instances or prove their reshaping into those abstracts.','', 'The inherited `array_decoder_phase_mux_allowance` is **56.584 mm²**, or 1.79876 µm² per four-bit selection. Its source is the October component budget (decoder25.002 + WL driver30.369 + PC driver0.269 + selector0.944 mm²). Despite the shorthand in the lead brief, it is **not a separately measured W5 integrated decoder/phase/mux macro**. It is retained as an explicitly assumed transfer allowance. W6 already contains analog readouts, so the old11.004 mm² receiver-strip term is not added. For books in the readable array, an additional **28.292 mm²** is allocated to digital access: 7,864,320 B ×8/4 =15,728,640 extra four-bit storage positions, one-half the fixed selection count. This proportional transfer is an assumption, not a new measurement; it does not qualify the missing phase control/output latches.','', 'W5’s stretched-pitch 1,280-row bank measured roughly22.5–24.4 ns slow-corner settling and a60 ns sampled reuse pass. The engine issues INDEX requests every three cycles: about60 ns at the20 ns target clock, or120 ns at the25 MHz/40 ns clock assumed here. The average4,163cycles/1,280rows is3.252cycles/row including schedule overhead. A60 ns reuse interval is compatible with those request spacings; it does **not** support one row per20 ns, nor prove the one-cycle enable-to-capture contract. W6’s shorter/different joins need their own extracted timing. No W5 timing is relabeled as measured W6 timing.','', 'One engine still follows ceil(2 ×0.6 GMAC/s /(25 MHz ×409,600/4,163)) =1. The6.137 mm² synthesized W2b engine is budgeted at12.274 mm² using assumed50% utilization because routed area is unavailable. Its shared layer-row bus,25 MHz clock and contention schedule are unqualified. Each partition gets its own full engine plus4 mm²/40 mW link allowance. The original dynamic-logic and ordinary-register allowances remain, including their conservative duplication risk.','', '### Memory and lever area table','', 'Total block area in mm², before chip pads, halos and outer placement whitespace. The 144-declaration /321-instance mutable inventory is unchanged: 8,501,818 array bits plus237,524 register bits. No KV8 or state reserve is used in this section.','', '| Memory | Levers off | Levers on |','|---|---:|---:|']
for mem in cfg['memory_scenarios']:
 values={r['levers']:r['total_mm2'] for r in rows if r['memory']==mem};lines.append(f"| {mem} | {values['off']:.3f} | {values['on']:.3f} |")
books=next(r['total_mm2'] for r in rows if r['memory']=='sram_open_macro' and r['levers']=='books')
lines+=['', '`sram_open_macro`: measured64/128/256/512×8 LEF rectangles, independently banked per array instance and byte lane;539.853 mm² of SRAM rectangles +10% assumed internal placement =593.838 mm². `sram_4k_research`: project0.9479839488 mm²/4,096 B, independently capacity-rounded, +10% allowance =553.717 mm²; it is not a drop-in compiled SRAM. `sram_dense_custom`: assumed12 µm²/bit effective including periphery, +10% bank-group placement =112.224 mm²; a foundry/compiler macro must replace that assumption.','', 'Levers off retain FP32 frontend and binary books. Levers on enable **frontend INT8** (2,074,560 B instead of8,298,240 B, requiring model-accuracy re-validation) and **books in the pitch-matched array** (5.536731543/4 µm² per bit plus the explicit digital-access allowance). Books-in-array changes physical storage, not numerical values; the read/access implementation still needs bit-exact validation. Book deduplication is not credited: all7,864,320 K64 padded slots remain, rather than assuming the7,765,892 used-byte figure can be compacted without address/remapping cost. No lower power or arithmetic area is inferred from INT8.','', f"The **open-SRAM, books-only** case is **{books:.3f} mm²**. It keeps FP32 frontend and all original mutable state and therefore needs no numerical accuracy change. This is the interpretation used for the requested no-custom-SRAM/no-accuracy-change option. The separate open-SRAM 'levers on' case includes INT8 and **does** need accuracy re-validation; those conditions cannot both describe the same case.", '', '### Completed physical screens','', '| Case | Outline mm | Block mm² | Core util. | Assumed W | Supply pairs / signal pads | VDD/VSS mV | Combined loss | PDN / IR | Fits26×33? |','|---|---|---:|---:|---:|---:|---:|---:|---|---|']
for label,p in zip(labels,physical):lines.append(f"| {label} | {p['die_width_mm']:g} × {p['die_height_mm']:g} | {p['block_area_mm2']:.3f} | {p['placement_utilization']:.1%} | {p['power_assumed_w']:.3f} | {p['supply_pad_pairs']} /16 | {p['worst_ir_drop_v']*1000:.1f} /{p['worst_ground_rise_v']*1000:.1f} | {p['combined_worst_bound_v']/3.3:.2%} | {'PASS' if p['physical_screen_pass'] else 'FAIL'} | {'YES' if p['fits_assumed26x33_reticle'] else 'NO'} |")
lines+=['', 'One-die search compares dense-SRAM levers on/off; on is smaller. Dense-SRAM/off has740.618 mm² of blocks but fails the26×33 mm rectangle under this packing policy; its smallest searched rectangle is30×31 mm and was not sent to EDA. Open-SRAM/books-only also fails one26×33 field by block area, so the selected implementation screen uses two dies.','', 'Minimum means the smallest integer-mm rectangle in the recorded deterministic shelf search (width16–49 mm, height up to54 mm, width≤height, aspect≤33/26,700 µm margin,30 µm macro halos). It is not a proof of global packing optimality. A/B are area-balanced abstract tiles, not a completed encoder/decoder partition. The exact instance assignments and replicated engines are in the manifests. Layer buses, codebook service, memory ownership and cross-die bandwidth have not been implemented.','', 'All cases pass both `check_power_grid` calls, both IR solves, independent macro halo/boundary checks and zero positive-area VDD/VSS overlaps in special wires, macro pins and via enclosures. The reported IR percentage uses the conservative sum of separate worst supply drop and ground rise divided by3.3 V. It excludes package, bond wires, macro-internal resistance, transients and EM, and uses technology-LEF screening resistances rather than qualified extraction. All block macros are LEF abstracts; no routed internals or functional IO signal wiring are implied.','', 'Core rings and grid use40 µm Metal4/Metal5 conductors,400 µm strap pitch; vertical Metal4 macro pins connect to Metal5 straps. Supply pads have Metal2 feeds. The power-derived minimum is ceil(2×P/(3.3V×25mA)), rounded to a multiple of four. Based on the prior IR failures, these screens reserve48pairs on the one-die case and32pairs on each split die. The assumed25mA pad budget is not package/EM qualification. Sixteen actual signal pad instances, four corners and real abutting fillers are also placed.','', 'All loads retain the earlier assumed1.08 W whole-chip allocation; split total is1.31 W including an extra engine and two link allowances. W6 complete-row energy is unavailable and W2b workload power is unannotated, so neither smaller area nor IR success establishes sub-watt operation. Per-block area and load tables are in `credible_results.json` and `blocks_credible.json`.','', '### Credible design-point artifacts','']
for label,p in zip(labels,physical):lines.append(f"- **{label}:** [PNG]({p['artifacts']['png']}), [IR heatmap]({p['artifacts']['heatmap']}), [DEF]({p['artifacts']['def']}), [ODB]({p['artifacts']['odb']}), [Tcl]({p['artifacts']['tcl']}).")
lines+=['', '[Open-SRAM INT8 two-die layout](credible_open_on_two_die_floorplan.png); [open-SRAM FP32 two-die layout](credible_open_books_two_die_floorplan.png). [Open-SRAM INT8 two-die heatmap](credible_open_on_two_die_ir_heatmap.png); [open-SRAM FP32 two-die heatmap](credible_open_books_two_die_ir_heatmap.png). Heatmaps are per-macro terminal voltages exported by OpenROAD, not measured macro-internal gradients.','', 'Reproduce using [CREDIBLE_COMMANDS.md](CREDIBLE_COMMANDS.md). Exact input hashes/snapshots, execution commands, return codes, free-space minima and verification records are in [credible_results.json](credible_results.json), each run’s immutable `blocks_snapshot.json` and `execution.json`. The W5 as-built section above and its artifacts are preserved. An initial preparation typo/missing-Tcl launch and the earlier pitch trials missing book digital-access area are preserved in `credible_launch_failure.json` and `credible_superseded_access_allowance.json`; they receive no final pass credit. EDA stayed local at nice10,≤4threads, with≥22GiB free and600s/run guards.','']
changed=[s['source'] for s in sourcecheck if not s['unchanged']];lines.append('Final W6/W5/W2b hash check: '+('unchanged since the frozen credible snapshot.' if not changed else 'updated files: '+', '.join(changed)+'. See refresh audit for material input comparison.'))
