body='\n'.join(lines)+'\n';segments=re.split(r'(`[^`]*`|\[[^\]]*\]\([^)]*\))',body)
for i in range(0,len(segments),2):
 t=segments[i];t=re.sub(r'\b(uses|at|At|and|by|the|The|is|full|selected|includes|are|after|to|about|explicit|sums|all|only|than|nice|assumed|roughly|reports|including|with|per|old|from|plus|a|A|or|average|measured|project|has|one|width|decoder|driver|selector)(?=\d)',r'\1 ',t);t=re.sub(r'(?<=\d)(mm²|mm2|mm|µm²|µm|um2|ns|pJ|GiB|threads|pairs|pair|supply|output|raw|receiver|array|bank|selection|matrix|row|lane|phase|cycles|cycle|bits|bytes)',r' \1',t);segments[i]=t
body=''.join(segments)
